nextflow_process {
    name "FILTER_CALLS"
    script "../main.nf"
    process "FILTER_CALLS"

    test("retain supported deletion in target") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(
                    id: 'sample',
                    vcf: file("${moduleDir}/tests/data/sample.calls.vcf", checkIfExists: true),
                    target: file("${moduleDir}/tests/data/target.bed", checkIfExists: true),
                    summary: file("${moduleDir}/tests/data/sample.mosdepth.summary.txt", checkIfExists: true),
                    fai: file("${moduleDir}/tests/data/reference.fa.fai", checkIfExists: true)
                )
                """
            }
        }

        then {
            assert process.success
            def vcf = file(process.out[0].vcf[0])
            assert vcf.text.readLines().count { line -> !line.startsWith('#') } == 1
            assert vcf.text.contains('SUPPORT=20')
        }
    }
}
